44	/****************************************************************************
45	 * Pre-processor Definitions
46	 ****************************************************************************/
47	
48	#define SDIO_BLOCK_SIZE     512
49	#define SDIO_INIT_MAX_RETRY 10
50	
51	#define SDIO_FUNC_0         0
52	#define SDIO_FUNC_1         1
53	
54	/* SDIO CCCR registers */
55	
56	#define SD_IO_CCCR_FN_ENABLE    0x02
57	#define SD_IO_CCCR_FN_READY     0x03
58	#define SD_IO_CCCR_INT_ENABLE   0x04
59	#define SD_IO_CCCR_BUS_WIDTH    0x07
60	
61	/* SDIO FBR registers */
62	
63	#define SD_IO_FBR_START         0x100
64	
65	/* SDIO block size registers */
66	
67	#define SD_IO_CCCR_BLKSIZEL     0x10
68	#define SD_IO_CCCR_BLKSIZEH     0x11
69	
70	/* SDIO wrapper macros for NuttX SDIO interface */
71	
72	#define SDIO_WRITEFUNC(dev, func, addr, data, len) \
73	    sdio_io_rw_extended((dev), true, (func), (addr), true, (data), (len), 1)
74	
75	#define SDIO_READFUNC(dev, func, addr, data, len) \
76	    sdio_io_rw_extended((dev), false, (func), (addr), true, (data), (len), 1)
77	
78	#define SDIO_READBLOCK(dev, reg, data, blocks) \
79	    sdio_io_rw_extended((dev), false, SDIO_FUNC_1, (reg), true, (data), SDIO_BLOCK_SIZE, (blocks))
80	
81	#define SDIO_WRITEBLOCK(dev, reg, data, blocks) \
82	    sdio_io_rw_extended((dev), true, SDIO_FUNC_1, (reg), true, (data), SDIO_BLOCK_SIZE, (blocks))
83	
84	#define SDIO_SETFREQUENCY(dev, freq) \
85	    ((dev)->clock((dev), CLOCK_SD_TRANSFER_4BIT))
86	
87	#define SDIO_SETBUSWIDTH(dev, width) \
88	    sdio_set_wide_bus(dev)
89	
90	#define SDIO_WAITINT(dev, ticks) \
91	    ((dev)->eventwait(dev))
