122	/****************************************************************************
123	 * Name: hosted_sdio_set_blocksize
124	 *
125	 * Description:
126	 *   Set SDIO function block size.
127	 *
128	 ****************************************************************************/
129	
130	static int hosted_sdio_set_blocksize(struct sdio_dev_s *dev, uint8_t fn,
131	                                     uint16_t size)
132	{
133	    uint8_t lo = size & 0xff;
134	    uint8_t hi = (size >> 8) & 0xff;
135	    uint16_t offset = SD_IO_FBR_START * fn;
136	    int ret;
137	
138	    ret = SDIO_WRITEFUNC(dev, SDIO_FUNC_0,
139	                         offset + SD_IO_CCCR_BLKSIZEL, &lo, 1);
140	    if (ret < 0) {
141	        return ret;
142	    }
143	
144	    ret = SDIO_WRITEFUNC(dev, SDIO_FUNC_0,
145	                         offset + SD_IO_CCCR_BLKSIZEH, &hi, 1);
146	    if (ret < 0) {
147	        return ret;
148	    }
149	
150	    return 0;
151	}
