153	/****************************************************************************
154	 * Name: hosted_sdio_card_fn_init
155	 *
156	 * Description:
157	 *   Initialize SDIO card function 1.
158	 *
159	 ****************************************************************************/
160	
161	static int hosted_sdio_card_fn_init(struct sdio_dev_s *dev)
162	{
163	    uint8_t ioe = 0;
164	    uint8_t ior = 0;
165	    uint8_t ie = 0;
166	    int i;
167	    int ret;
168	
169	    /* Enable function 1 */
170	
171	    ret = SDIO_READFUNC(dev, SDIO_FUNC_0, SD_IO_CCCR_FN_ENABLE, &ioe, 1);
172	    if (ret < 0) {
173	        return ret;
174	    }
175	
176	    wlinfo("IOE: 0x%02x\n", ioe);
177	
178	    ioe |= (1 << 1);  /* FUNC1_EN_MASK */
179	    ret = SDIO_WRITEFUNC(dev, SDIO_FUNC_0, SD_IO_CCCR_FN_ENABLE, &ioe, 1);
180	    if (ret < 0) {
181	        return ret;
182	    }
183	
184	    /* Wait for card to become ready */
185	
186	    for (i = 0; i < SDIO_INIT_MAX_RETRY; i++) {
187	        ret = SDIO_READFUNC(dev, SDIO_FUNC_0, SD_IO_CCCR_FN_READY, &ior, 1);
188	        if (ret < 0) {
189	            return ret;
190	        }
191	
192	        wlinfo("IOR: 0x%02x\n", ior);
193	        if (ior & (1 << 1)) {
194	            break;
195	        }
196	
197	        usleep(10 * 1000);
198	    }
199	
200	    if (i >= SDIO_INIT_MAX_RETRY) {
201	        wlerr("ERROR: SDIO card failed to become ready\n");
202	        return -ETIMEDOUT;
203	    }
204	
205	    /* Enable interrupts for function 1 and master enable */
206	
207	    ret = SDIO_READFUNC(dev, SDIO_FUNC_0, SD_IO_CCCR_INT_ENABLE, &ie, 1);
208	    if (ret < 0) {
209	        return ret;
210	    }
211	
212	    wlinfo("IE: 0x%02x\n", ie);
213	
214	    ie |= (1 << 0) | (1 << 1);  /* Master enable + FUNC1 */
215	    ret = SDIO_WRITEFUNC(dev, SDIO_FUNC_0, SD_IO_CCCR_INT_ENABLE, &ie, 1);
216	    if (ret < 0) {
217	        return ret;
218	    }
219	
220	    /* Set FN0 and FN1 block size to 512 */
221	
222	    ret = hosted_sdio_set_blocksize(dev, SDIO_FUNC_0, SDIO_BLOCK_SIZE);
223	    if (ret < 0) {
224	        return ret;
225	    }
226	
227	    ret = hosted_sdio_set_blocksize(dev, SDIO_FUNC_1, SDIO_BLOCK_SIZE);
228	    if (ret < 0) {
229	        return ret;
230	    }
231	
232	    return 0;
233	}
