239	/****************************************************************************
240	 * Name: hosted_sdio_card_init
241	 *
242	 * Description:
243	 *   Initialize SDIO card.
244	 *
245	 ****************************************************************************/
246	
247	int hosted_sdio_card_init(void *ctx, bool show_config)
248	{
249	    struct hosted_sdio_context *context = (struct hosted_sdio_context *)ctx;
250	    struct sdio_dev_s *dev;
251	    int ret;
252	
253	    if (!context || !context->sdio_dev) {
254	        return -EINVAL;
255	    }
256	
257	    dev = context->sdio_dev;
258	
259	    /* Initialize SDIO bus */
260	
261	    SDIO_SETFREQUENCY(dev, context->clock_freq_khz * 1000);
262	
263	    if (context->bus_width == 4) {
264	        ret = SDIO_SETBUSWIDTH(dev, 4);
265	        if (ret < 0) {
266	            wlerr("ERROR: Failed to set 4-bit bus width: %d\n", ret);
267	            return ret;
268	        }
269	    }
270	
271	    /* Initialize card function */
272	
273	    ret = hosted_sdio_card_fn_init(dev);
274	    if (ret < 0) {
275	        wlerr("ERROR: Failed to initialize SDIO card function: %d\n", ret);
276	        return ret;
277	    }
278	
279	    wlinfo("SDIO card initialized successfully\n");
280	    return 0;
281	}
