366	/****************************************************************************
367	 * Name: hosted_sdio_read_block
368	 *
369	 * Description:
370	 *   Read SDIO block.
371	 *
372	 ****************************************************************************/
373	
374	int hosted_sdio_read_block(void *ctx, uint32_t reg, uint8_t *data,
375	                           uint16_t size, bool lock_required)
376	{
377	    struct hosted_sdio_context *context = (struct hosted_sdio_context *)ctx;
378	    struct sdio_dev_s *dev;
379	    int ret;
380	
381	    if (!context || !context->sdio_dev || !data) {
382	        return -EINVAL;
383	    }
384	
385	    dev = context->sdio_dev;
386	
387	    if (lock_required) {
388	        nxmutex_lock(&context->lock);
389	    }
390	
391	    /* Use block mode transfer */
392	
393	    uint16_t blocks = size / SDIO_BLOCK_SIZE;
394	    uint16_t remainder = size % SDIO_BLOCK_SIZE;
395	
396	    if (blocks > 0) {
397	        ret = SDIO_READBLOCK(dev, reg, data, blocks);
398	        if (ret < 0) {
399	            goto errout;
400	        }
401	    }
402	
403	    if (remainder > 0) {
404	        /* Read remainder using byte mode */
405	
406	        ret = SDIO_READFUNC(dev, SDIO_FUNC_1,
407	                            reg + blocks * SDIO_BLOCK_SIZE,
408	                            data + blocks * SDIO_BLOCK_SIZE,
409	                            remainder);
410	        if (ret < 0) {
411	            goto errout;
412	        }
413	    }
414	
415	    ret = 0;
416	
417	errout:
418	    if (lock_required) {
419	        nxmutex_unlock(&context->lock);
420	    }
421	
422	    return ret;
423	}
