508	/****************************************************************************
509	 * Name: hosted_sdio_init
510	 *
511	 * Description:
512	 *   Initialize SDIO transport and register OSI functions.
513	 *
514	 ****************************************************************************/
515	
516	int hosted_sdio_init(void)
517	{
518	    struct sdio_dev_s *sdio_dev;
519	
520	    /* Allocate SDIO context */
521	
522	    g_sdio_ctx = (struct hosted_sdio_context *)kumm_malloc(
523	                     sizeof(struct hosted_sdio_context));
524	    if (!g_sdio_ctx) {
525	        return -ENOMEM;
526	    }
527	
528	    memset(g_sdio_ctx, 0, sizeof(struct hosted_sdio_context));
529	
530	    /* Initialize SDIO device */
531	
532	    sdio_dev = sdio_initialize(CONFIG_ESP_HOSTED_SDIO_SLOT);
533	    if (!sdio_dev) {
534	        wlerr("ERROR: Failed to initialize SDIO slot %d\n",
535	              CONFIG_ESP_HOSTED_SDIO_SLOT);
536	        kumm_free(g_sdio_ctx);
537	        g_sdio_ctx = NULL;
538	        return -ENODEV;
539	    }
540	
541	    g_sdio_ctx->sdio_dev = sdio_dev;
542	    g_sdio_ctx->clock_freq_khz = CONFIG_ESP_HOSTED_SDIO_FREQ_KHZ;
543	    g_sdio_ctx->bus_width = CONFIG_ESP_HOSTED_SDIO_BUS_WIDTH_4BIT ? 4 : 1;
544	    g_sdio_ctx->slot = CONFIG_ESP_HOSTED_SDIO_SLOT;
545	
546	    nxmutex_init(&g_sdio_ctx->lock);
547	
548	    /* Register SDIO functions in OSI */
549	
550	    g_h.funcs->_h_sdio_card_init = hosted_sdio_card_init;
551	    g_h.funcs->_h_sdio_card_deinit = hosted_sdio_card_deinit;
552	    g_h.funcs->_h_sdio_read_reg = hosted_sdio_read_reg;
553	    g_h.funcs->_h_sdio_write_reg = hosted_sdio_write_reg;
554	    g_h.funcs->_h_sdio_read_block = hosted_sdio_read_block;
555	    g_h.funcs->_h_sdio_write_block = hosted_sdio_write_block;
556	    g_h.funcs->_h_sdio_wait_slave_intr = hosted_sdio_wait_slave_intr;
557	
558	    /* Set bus init/deinit */
559	
560	    g_h.funcs->_h_bus_init = hosted_sdio_bus_init;
561	    g_h.funcs->_h_bus_deinit = hosted_sdio_bus_deinit;
562	
563	    wlinfo("SDIO transport initialized\n");
564	    return 0;
565	}
