567	/****************************************************************************
568	 * Name: hosted_sdio_bus_init
569	 *
570	 * Description:
571	 *   Initialize SDIO bus (called by esp_hosted_init).
572	 *
573	 ****************************************************************************/
574	
575	void *hosted_sdio_bus_init(void)
576	{
577	    int ret;
578	
579	    if (!g_sdio_ctx) {
580	        ret = hosted_sdio_init();
581	        if (ret < 0) {
582	            return NULL;
583	        }
584	    }
585	
586	    /* Initialize card */
587	
588	    ret = hosted_sdio_card_init(g_sdio_ctx, true);
589	    if (ret < 0) {
590	        wlerr("ERROR: SDIO card init failed: %d\n", ret);
591	        return NULL;
592	    }
593	
594	    return g_sdio_ctx;
595	}
596	
597	/****************************************************************************
598	 * Name: hosted_sdio_bus_deinit
599	 *
600	 * Description:
601	 *   Deinitialize SDIO bus.
602	 *
603	 ****************************************************************************/
604	
605	int hosted_sdio_bus_deinit(void *ctx)
606	{
607	    struct hosted_sdio_context *context = (struct hosted_sdio_context *)ctx;
608	
609	    if (context) {
610	        hosted_sdio_card_deinit(context);
611	        nxmutex_destroy(&context->lock);
612	        kumm_free(context);
613	        g_sdio_ctx = NULL;
614	    }
615	
616	    return 0;
617	}
