177	
178	static void *hosted_thread_create(const char *tname, uint32_t tprio,
179	                                  uint32_t tstack_size,
180	                                  void (*start_routine)(void const *),
181	                                  void *sr_arg)
182	{
183	    pthread_t *thread;
184	    pthread_attr_t attr;
185	    struct sched_param param;
186	    struct hosted_thread_arg *targ;
187	    int ret;
188	
189	    thread = (pthread_t *)kumm_malloc(sizeof(pthread_t));
190	    if (!thread) {
191	        return NULL;
192	    }
193	
194	    targ = (struct hosted_thread_arg *)kumm_malloc(sizeof(struct hosted_thread_arg));
195	    if (!targ) {
196	        kumm_free(thread);
197	        return NULL;
198	    }
199	
200	    targ->start_routine = start_routine;
201	    targ->arg = sr_arg;
202	
203	    pthread_attr_init(&attr);
204	    param.sched_priority = tprio;
205	    pthread_attr_setschedparam(&attr, &param);
206	    pthread_attr_setstacksize(&attr, tstack_size);
207	    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
208	
209	    ret = pthread_create(thread, &attr, hosted_thread_wrapper, targ);
210	    if (ret != 0) {
211	        kumm_free(thread);
212	        kumm_free(targ);
213	        return NULL;
214	    }
215	
216	    return thread;
217	}
