267	 * Queue Functions
268	 ****************************************************************************/
269	
270	static void *hosted_create_queue(uint32_t qnum_elem, uint32_t qitem_size)
271	{
272	    mqd_t *mqd;
273	    struct mq_attr attr;
274	    char mqname[32];
275	    static int queue_id = 0;
276	
277	    mqd = (mqd_t *)kumm_malloc(sizeof(mqd_t));
278	    if (!mqd) {
279	        return NULL;
280	    }
281	
282	    snprintf(mqname, sizeof(mqname), "/hosted_q%d", queue_id++);
283	
284	    attr.mq_flags = 0;
285	    attr.mq_maxmsg = qnum_elem;
286	    attr.mq_msgsize = qitem_size;
287	    attr.mq_curmsgs = 0;
288	
289	    *mqd = mq_open(mqname, O_CREAT | O_RDWR, 0666, &attr);
290	    if (*mqd == (mqd_t)-1) {
291	        kumm_free(mqd);
292	        return NULL;
293	    }
294	
295	    return mqd;
296	}
297	
298	static int hosted_queue_item(void *queue_handle, void *item, int timeout)
299	{
300	    mqd_t *mqd = (mqd_t *)queue_handle;
301	    struct mq_attr attr;
302	    unsigned int prio = 0;
303	
304	    if (!mqd || !item) {
305	        return -EINVAL;
306	    }
307	
308	    mq_getattr(*mqd, &attr);
309	
310	    if (timeout == HOSTED_BLOCK_MAX) {
311	        return mq_send(*mqd, (const char *)item, attr.mq_msgsize, prio);
312	    } else if (timeout == 0) {
313	        /* Non-blocking */
314	
315	        struct timespec ts;
316	        clock_gettime(CLOCK_REALTIME, &ts);
317	        ts.tv_nsec += 1000000; /* 1ms */
318	        if (ts.tv_nsec >= 1000000000) {
319	            ts.tv_sec++;
320	            ts.tv_nsec -= 1000000000;
321	        }
322	        return mq_timedsend(*mqd, (const char *)item, attr.mq_msgsize, prio, &ts);
323	    } else {
324	        struct timespec ts;
325	        clock_gettime(CLOCK_REALTIME, &ts);
326	        ts.tv_sec += timeout / 1000;
327	        ts.tv_nsec += (timeout % 1000) * 1000000;
328	        if (ts.tv_nsec >= 1000000000) {
329	            ts.tv_sec++;
330	            ts.tv_nsec -= 1000000000;
331	        }
332	        return mq_timedsend(*mqd, (const char *)item, attr.mq_msgsize, prio, &ts);
333	    }
334	}
335	
336	static int hosted_dequeue_item(void *queue_handle, void *item, int timeout)
337	{
338	    mqd_t *mqd = (mqd_t *)queue_handle;
339	    struct mq_attr attr;
340	    unsigned int prio = 0;
341	    ssize_t ret;
342	
343	    if (!mqd || !item) {
344	        return -EINVAL;
345	    }
346	
347	    mq_getattr(*mqd, &attr);
348	
349	    if (timeout == HOSTED_BLOCK_MAX) {
350	        ret = mq_receive(*mqd, (char *)item, attr.mq_msgsize, &prio);
351	    } else if (timeout == 0) {
352	        struct timespec ts;
353	        clock_gettime(CLOCK_REALTIME, &ts);
354	        ts.tv_nsec += 1000000; /* 1ms */
355	        if (ts.tv_nsec >= 1000000000) {
356	            ts.tv_sec++;
357	            ts.tv_nsec -= 1000000000;
358	        }
359	        ret = mq_timedreceive(*mqd, (char *)item, attr.mq_msgsize, &prio, &ts);
360	    } else {
361	        struct timespec ts;
362	        clock_gettime(CLOCK_REALTIME, &ts);
363	        ts.tv_sec += timeout / 1000;
364	        ts.tv_nsec += (timeout % 1000) * 1000000;
365	        if (ts.tv_nsec >= 1000000000) {
366	            ts.tv_sec++;
367	            ts.tv_nsec -= 1000000000;
368	        }
369	        ret = mq_timedreceive(*mqd, (char *)item, attr.mq_msgsize, &prio, &ts);
370	    }
371	
372	    return (ret < 0) ? -errno : 0;
373	}
374	
375	static int hosted_queue_msg_waiting(void *queue_handle)
376	{
377	    mqd_t *mqd = (mqd_t *)queue_handle;
378	    struct mq_attr attr;
379	
380	    if (!mqd) {
381	        return 0;
382	    }
383	
384	    mq_getattr(*mqd, &attr);
385	    return attr.mq_curmsgs;
386	}
387	
388	static int hosted_destroy_queue(void *queue_handle)
389	{
390	    mqd_t *mqd = (mqd_t *)queue_handle;
391	
392	    if (mqd) {
393	        mq_close(*mqd);
394	        kumm_free(mqd);
395	    }
396	    return 0;
397	}
398	
399	static int hosted_reset_queue(void *queue_handle)
400	{
401	    /* NuttX doesn't have a direct queue reset, drain messages */
402	
403	    mqd_t *mqd = (mqd_t *)queue_handle;
404	    struct mq_attr attr;
405	    char buf[256];
406	    unsigned int prio;
407	
408	    if (!mqd) {
409	        return -EINVAL;
410	    }
411	
412	    mq_getattr(*mqd, &attr);
413	    while (attr.mq_curmsgs > 0) {
414	        mq_timedreceive(*mqd, buf, attr.mq_msgsize, &prio, NULL);
415	        attr.mq_curmsgs--;
416	    }
417	
418	    return 0;
419	}
