421	/****************************************************************************
422	 * Mutex Functions
423	 ****************************************************************************/
424	
425	static void *hosted_create_mutex(void)
426	{
427	    mutex_t *mutex = (mutex_t *)kumm_malloc(sizeof(mutex_t));
428	    if (mutex) {
429	        nxmutex_init(mutex);
430	    }
431	    return mutex;
432	}
433	
434	static int hosted_lock_mutex(void *mutex_handle, int timeout_ms)
435	{
436	    mutex_t *mutex = (mutex_t *)mutex_handle;
437	    int ret;
438	
439	    if (!mutex) {
440	        return -EINVAL;
441	    }
442	
443	    if (timeout_ms == HOSTED_BLOCK_MAX) {
444	        ret = nxmutex_lock(mutex);
445	    } else if (timeout_ms == 0) {
446	        ret = nxmutex_trylock(mutex);
447	    } else {
448	        /* NuttX mutex doesn't support timed lock directly,
449	         * use trylock with retry
450	         */
451	
452	        int elapsed = 0;
453	        while (elapsed < timeout_ms) {
454	            ret = nxmutex_trylock(mutex);
455	            if (ret == 0) {
456	                return 0;
457	            }
458	            nxsig_usleep(1000); /* 1ms */
459	            elapsed++;
460	        }
461	        ret = -ETIMEDOUT;
462	    }
463	
464	    return ret;
465	}
466	
467	static int hosted_unlock_mutex(void *mutex_handle)
468	{
469	    mutex_t *mutex = (mutex_t *)mutex_handle;
470	    if (!mutex) {
471	        return -EINVAL;
472	    }
473	    return nxmutex_unlock(mutex);
474	}
475	
476	static int hosted_destroy_mutex(void *mutex_handle)
477	{
478	    mutex_t *mutex = (mutex_t *)mutex_handle;
479	    if (mutex) {
480	        nxmutex_destroy(mutex);
481	        kumm_free(mutex);
482	    }
483	    return 0;
484	}
