517	static int hosted_get_semaphore(void *semaphore_handle, int timeout_ms)
518	{
519	    sem_t *sem = (sem_t *)semaphore_handle;
520	    int ret;
521	
522	    if (!sem) {
523	        return -EINVAL;
524	    }
525	
526	    if (timeout_ms == HOSTED_BLOCK_MAX) {
527	        ret = nxsem_wait(sem);
528	    } else if (timeout_ms == 0) {
529	        ret = nxsem_trywait(sem);
530	    } else {
531	        struct timespec ts;
532	        clock_gettime(CLOCK_REALTIME, &ts);
533	        ts.tv_sec += timeout_ms / 1000;
534	        ts.tv_nsec += (timeout_ms % 1000) * 1000000;
535	        if (ts.tv_nsec >= 1000000000) {
536	            ts.tv_sec++;
537	            ts.tv_nsec -= 1000000000;
538	        }
539	        ret = nxsem_timedwait(sem, &ts);
540	    }
541	
542	    return ret;
543	}
