555	/****************************************************************************
556	 * Timer Functions
557	 ****************************************************************************/
558	
559	static void *hosted_timer_start(const char *name, int duration_ms,
560	                                int type, void (*timeout_handler)(void *),
561	                                void *arg)
562	{
563	    struct hosted_timer_s *timer;
564	    struct sigevent sev;
565	    struct itimerspec its;
566	
567	    timer = (struct hosted_timer_s *)kumm_malloc(sizeof(struct hosted_timer_s));
568	    if (!timer) {
569	        return NULL;
570	    }
571	
572	    timer->callback = timeout_handler;
573	    timer->arg = arg;
574	
575	    sev.sigev_notify = SIGEV_SIGNAL;
576	    sev.sigev_signo = TIMER_SIGNAL;
577	    sev.sigev_value.sival_ptr = timer;
578	
579	    if (timer_create(CLOCK_REALTIME, &sev, &timer->timer_id) != 0) {
580	        kumm_free(timer);
581	        return NULL;
582	    }
583	
584	    its.it_value.tv_sec = duration_ms / 1000;
585	    its.it_value.tv_nsec = (duration_ms % 1000) * 1000000;
586	    its.it_interval.tv_sec = (type == 1) ? its.it_value.tv_sec : 0;
587	    its.it_interval.tv_nsec = (type == 1) ? its.it_value.tv_nsec : 0;
588	
589	    if (timer_settime(timer->timer_id, 0, &its, NULL) != 0) {
590	        timer_delete(timer->timer_id);
591	        kumm_free(timer);
592	        return NULL;
593	    }
594	
595	    return timer;
596	}
597	
598	static int hosted_timer_stop(void *timer_handle)
599	{
600	    struct hosted_timer_s *timer = (struct hosted_timer_s *)timer_handle;
601	    if (timer) {
602	        timer_delete(timer->timer_id);
603	        kumm_free(timer);
604	    }
605	    return 0;
606	}
607	
608	static uint64_t hosted_get_time_ms(void)
609	{
610	    struct timespec ts;
611	    clock_gettime(CLOCK_MONOTONIC, &ts);
612	    return (uint64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
613	}
