#include <arch/chip/gpio_sig_map.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* ESP32-P4 SDMMC Slot 1 GPIO matrix signal indices
 *
 * The ESP32-P4 has two SDMMC slots:
 *   Slot 0: Uses IOMUX (dedicated pins) for TF card
 *   Slot 1: Uses GPIO matrix for ESP-Hosted SDIO to ESP32-C6
 *
 * GPIO signal indices for SDMMC slot 1 (from gpio_sig_map.h):
 *   SD_CARD_CCLK_2_PAD_OUT_IDX  - CLK output
 *   SD_CARD_CCMD_2_PAD_IN_IDX   - CMD input
 *   SD_CARD_CCMD_2_PAD_OUT_IDX  - CMD output
 *   SD_CARD_CDATA0_2_PAD_IN_IDX - D0 input
 *   SD_CARD_CDATA0_2_PAD_OUT_IDX- D0 output
 *   SD_CARD_CDATA1_2_PAD_IN_IDX - D1 input
 *   SD_CARD_CDATA1_2_PAD_OUT_IDX- D1 output
 *   SD_CARD_CDATA2_2_PAD_IN_IDX - D2 input
 *   SD_CARD_CDATA2_2_PAD_OUT_IDX- D2 output
 *   SD_CARD_CDATA3_2_PAD_IN_IDX - D3 input
 *   SD_CARD_CDATA3_2_PAD_OUT_IDX- D3 output
 */

/* Default GPIO pin assignments for slot 1 (ESP-Hosted to ESP32-C6).
 * These should be configured via Kconfig for the specific board.
 */

#ifndef CONFIG_ESP32P4_SDMMC_SLOT1_PIN_CLK
#  define CONFIG_ESP32P4_SDMMC_SLOT1_PIN_CLK  14
#endif

#ifndef CONFIG_ESP32P4_SDMMC_SLOT1_PIN_CMD
#  define CONFIG_ESP32P4_SDMMC_SLOT1_PIN_CMD  15
#endif

#ifndef CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D0
#  define CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D0   16
#endif

#ifndef CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D1
#  define CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D1   17
#endif

#ifndef CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D2
#  define CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D2   18
#endif

#ifndef CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D3
#  define CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D3   19
#endif

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: board_sdmmc_slot1_configure_pins
 *
 * Description:
 *   Configure GPIO matrix pins for SDMMC slot 1.
 *   Slot 1 uses GPIO matrix (not IOMUX) for ESP-Hosted SDIO connection
 *   to the onboard ESP32-C6.
 *
 *   Pin configuration:
 *   - CLK: Output only (push-pull)
 *   - CMD: Bidirectional (open-drain with pull-up)
 *   - D0-D3: Bidirectional (open-drain with pull-up)
 *
 ****************************************************************************/

#ifdef CONFIG_ESP32P4_SDMMC_SLOT1
static void board_sdmmc_slot1_configure_pins(void)
{
  /* CLK - output only (push-pull) */

  esp_configgpio(CONFIG_ESP32P4_SDMMC_SLOT1_PIN_CLK, OUTPUT | FUNCTION);
  esp_gpio_matrix_out(CONFIG_ESP32P4_SDMMC_SLOT1_PIN_CLK,
                       SD_CARD_CCLK_2_PAD_OUT_IDX, false, false);

  /* CMD - bidirectional (open-drain with pull-up) */

  esp_configgpio(CONFIG_ESP32P4_SDMMC_SLOT1_PIN_CMD,
                  INPUT | OUTPUT | OPEN_DRAIN | PULLUP);
  esp_gpio_matrix_out(CONFIG_ESP32P4_SDMMC_SLOT1_PIN_CMD,
                       SD_CARD_CCMD_2_PAD_OUT_IDX, false, false);
  esp_gpio_matrix_in(CONFIG_ESP32P4_SDMMC_SLOT1_PIN_CMD,
                      SD_CARD_CCMD_2_PAD_IN_IDX, false);

  /* D0 - bidirectional (open-drain with pull-up) */

  esp_configgpio(CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D0,
                  INPUT | OUTPUT | OPEN_DRAIN | PULLUP);
  esp_gpio_matrix_out(CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D0,
                       SD_CARD_CDATA0_2_PAD_OUT_IDX, false, false);
  esp_gpio_matrix_in(CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D0,
                      SD_CARD_CDATA0_2_PAD_IN_IDX, false);

  /* D1 - bidirectional (open-drain with pull-up) */

  esp_configgpio(CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D1,
                  INPUT | OUTPUT | OPEN_DRAIN | PULLUP);
  esp_gpio_matrix_out(CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D1,
                       SD_CARD_CDATA1_2_PAD_OUT_IDX, false, false);
  esp_gpio_matrix_in(CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D1,
                      SD_CARD_CDATA1_2_PAD_IN_IDX, false);

  /* D2 - bidirectional (open-drain with pull-up) */

  esp_configgpio(CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D2,
                  INPUT | OUTPUT | OPEN_DRAIN | PULLUP);
  esp_gpio_matrix_out(CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D2,
                       SD_CARD_CDATA2_2_PAD_OUT_IDX, false, false);
  esp_gpio_matrix_in(CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D2,
                      SD_CARD_CDATA2_2_PAD_IN_IDX, false);

  /* D3 - bidirectional (open-drain with pull-up) */

  esp_configgpio(CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D3,
                  INPUT | OUTPUT | OPEN_DRAIN | PULLUP);
  esp_gpio_matrix_out(CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D3,
                       SD_CARD_CDATA3_2_PAD_OUT_IDX, false, false);
  esp_gpio_matrix_in(CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D3,
                      SD_CARD_CDATA3_2_PAD_IN_IDX, false);

  syslog(LOG_INFO, "SDMMC slot 1 GPIO matrix pins configured: "
         "CLK=%d CMD=%d D0=%d D1=%d D2=%d D3=%d\n",
         CONFIG_ESP32P4_SDMMC_SLOT1_PIN_CLK,
         CONFIG_ESP32P4_SDMMC_SLOT1_PIN_CMD,
         CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D0,
         CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D1,
         CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D2,
         CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D3);
}
#endif /* CONFIG_ESP32P4_SDMMC_SLOT1 */

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: board_sdmmc_initialize
 *
 * Description:
 *   Initialize SDMMC subsystem for the ESP32-P4 contest board.
 *
 *   This function initializes:
 *   - Slot 0: External TF card (uses IOMUX dedicated pins)
 *   - Slot 1: ESP-Hosted SDIO to onboard ESP32-C6 (uses GPIO matrix)
 *
 *   Slot 0 is registered as MMC/SD device at /dev/mmcsd0.
 *   Slot 1 is used by esp-hosted for WiFi/BT via ESP32-C6.
 *
 * Returned Value:
 *   Zero (OK) is returned on success; A negated errno value is returned
 *   to indicate the nature of any failure.
 *
 ****************************************************************************/

int board_sdmmc_initialize(void)
{
  struct sdio_dev_s *sdio;
  int ret = OK;

#ifdef CONFIG_ESP32P4_SDMMC_SLOT0
  /* Initialize SDMMC slot 0 for external TF card (IOMUX pins) */

  sdio = sdio_initialize(0);
  if (!sdio)
    {
      syslog(LOG_ERR, "ERROR: Failed to initialize SDMMC slot 0 (TF card)\n");
      return -ENODEV;
    }

  /* Register the SD card driver at /dev/mmcsd0 */

  ret = mmcsd_slotinitialize(0, sdio);
  if (ret < 0)
    {
      syslog(LOG_ERR, "ERROR: Failed to register MMC/SD slot 0: %d\n", ret);
      return ret;
    }

  syslog(LOG_INFO, "SDMMC slot 0 (TF card) initialized\n");
#endif /* CONFIG_ESP32P4_SDMMC_SLOT0 */

#ifdef CONFIG_ESP32P4_SDMMC_SLOT1
  /* Configure GPIO matrix pins for slot 1 before initializing SDIO.
   * Slot 1 uses GPIO matrix (not IOMUX) for ESP-Hosted SDIO connection.
   * Pin configuration must happen before sdio_initialize() is called.
   */

  board_sdmmc_slot1_configure_pins();

  /* Initialize SDMMC slot 1 for ESP-Hosted SDIO to ESP32-C6 */

  sdio = sdio_initialize(1);
  if (!sdio)
    {
      syslog(LOG_ERR, "ERROR: Failed to initialize SDMMC slot 1 "
             "(ESP-Hosted SDIO)\n");
      return -ENODEV;
    }

  syslog(LOG_INFO, "SDMMC slot 1 (ESP-Hosted SDIO) initialized\n");
#endif /* CONFIG_ESP32P4_SDMMC_SLOT1 */

  return ret;
}

