/****************************************************************************
 * Contest 2026 team 000 board - boot initialization
 ****************************************************************************/

#include <nuttx/config.h>

#include <debug.h>
#include <errno.h>
#include <syslog.h>

#include <nuttx/board.h>

#include "board_sdmmc.h"
#include "board_esp_hosted.h"

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: openvela_board_initialize
 *
 * Description:
 *   Board-specific initialization called during boot.
 *   Initializes SDMMC (TF card + ESP-Hosted SDIO) and ESP-Hosted protocol.
 *
 ****************************************************************************/

void openvela_board_initialize(void)
{
  int ret;

#ifdef CONFIG_ESP32P4_SDMMC
  /* Initialize SDMMC subsystem:
   *   Slot 0: External TF card (IOMUX pins)
   *   Slot 1: ESP-Hosted SDIO to ESP32-C6 (GPIO matrix pins)
   */

  ret = board_sdmmc_initialize();
  if (ret < 0)
    {
      syslog(LOG_ERR, "ERROR: board_sdmmc_initialize failed: %d\n", ret);
    }
#endif

#ifdef CONFIG_ESP_HOSTED
  /* Initialize ESP-Hosted protocol for WiFi/BT via ESP32-C6.
   * Must be called after SDMMC slot 1 is initialized.
   */

  ret = board_esp_hosted_initialize();
  if (ret < 0)
    {
      syslog(LOG_ERR, "ERROR: board_esp_hosted_initialize failed: %d\n", ret);
    }
#endif
}

